import json
import re

with open("payload.json") as f:
    data = json.load(f)

MULT = {"K": 1e3, "M": 1e6, "B": 1e9}


def parse_money(raw):
    if raw is None or str(raw).strip() == "":
        return 0.0, None
    s = str(raw).strip()
    cur = None
    if "$" in s or "USD" in s.upper():
        cur = "USD"
    if "\u20ac" in s or "EUR" in s.upper():
        cur = "EUR"
    m = re.search(r"([-+]?\d[\d,]*\.?\d*)\s*([KMB])?", s.replace("USD", "").replace("EUR", ""), re.I)
    if not m:
        raise ValueError("Unparseable exposure: %r" % raw)
    amount = float(m.group(1).replace(",", ""))
    if m.group(2):
        amount *= MULT[m.group(2).upper()]
    return amount, cur


def parse_weight(w):
    if isinstance(w, (int, float)):
        return float(w)
    m = re.search(r"[-+]?\d*\.?\d+", str(w))
    if not m:
        raise ValueError("Unparseable weight: %r" % w)
    return float(m.group(0))


queries = []
nodes = []
for node in data["nodes"]:
    amount, cur = parse_money(node.get("exposure_raw"))
    props = {"name": node["name"], "tier": node["tier"], "exposure": amount,
             "currency": cur, "status": node["status"]}
    queries.append(("MERGE (n:Entity {id: $id}) SET n += $props", {"id": node["id"], "props": props}))
    nodes.append(dict(id=node["id"], **props))

ids = {n["id"] for n in nodes}
edges = []
for edge in data["edges"]:
    w = parse_weight(edge["weight"])
    assert edge["src"] in ids and edge["dst"] in ids, "dangling edge"
    assert 0.0 <= w <= 1.0, "weight out of range"
    queries.append(("MATCH (a:Entity {id: $src}), (b:Entity {id: $dst}) MERGE (a)-[r:SUPPLIES {rel: $rel}]->(b) SET r.weight = $w",
                    {"src": edge["src"], "dst": edge["dst"], "rel": edge["rel"], "w": w}))
    edges.append({"src": edge["src"], "dst": edge["dst"], "rel": edge["rel"], "weight": w})

assert all(n["exposure"] >= 0 for n in nodes)
print("Prepared %d parameterized Cypher statements" % len(queries))
print("CLEANED_GRAPH_JSON: " + json.dumps({"nodes": nodes, "edges": edges}, ensure_ascii=False))
print("ASSERTION_PASSED_GRAPH_COMMITTED")

